#include <iostream>
#include <stdexcept>
void publish(int reading, int& total, int& latest) {
    if (reading < 0 || reading > 100) {
        throw std::out_of_range("reading range");
    }
    total += reading;
    latest = reading;
}
int main() {
    int total = 0;
    int latest = 0;
    publish(4, total, latest);
    publish(3, total, latest);
    std::cout << "total: " << total << '\n';
    std::cout << "latest: " << latest << '\n';
}

#include <functional>
#include <iostream>
#include <stdexcept>
#include <vector>
int main() {
    int first = 0;
    int second = 0;
    std::vector<std::function<void(int)>> listeners;
    listeners.push_back([&](int value) {
        first += value;
        throw std::runtime_error("view failed");
    });
    listeners.push_back([&](int value) { second += value; });
    try {
        for (const auto& update : listeners) { update(5); }
    } catch (const std::runtime_error&) {
        std::cout << "delivery stopped\n";
    }
    std::cout << "first: " << first << '\n';
    std::cout << "second: " << second << '\n';
}
